// Offline test harness. These adapters are in memory and make no external calls.
const sheet = new Map();
const notifications = new Map();
const requests = new Map();
let sheetWriteCount = 0;
let notificationSendCount = 0;

function processRequest(payload, simulateFailure = "") {
  const record = {
    request_id: String(payload.request_id ?? "").trim(),
    email: String(payload.email ?? "").trim(),
    service: String(payload.service ?? "").trim(),
  };
  const { request_id: id, email, service } = record;
  if (!/^[A-Za-z0-9_-]{1,80}$/.test(id) || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) || !service) {
    return { status: 400, outcome: "invalid_request", request_id: id };
  }

  const fingerprint = JSON.stringify(record);
  const state = requests.get(id) ?? { fingerprint, logged: false, notified: false };
  if (state.fingerprint !== fingerprint) {
    return { status: 409, outcome: "request_id_conflict", request_id: id };
  }
  if (state.notified) {
    return { status: 200, outcome: "duplicate_replay", request_id: id };
  }
  requests.set(id, state);

  if (!state.logged) {
    if (simulateFailure === "sheet") {
      return { status: 503, outcome: "sheet_unavailable", request_id: id };
    }
    sheet.set(id, record);
    sheetWriteCount += 1;
    state.logged = true;
  }
  if (simulateFailure === "notification") {
    return { status: 503, outcome: "notification_unavailable", request_id: id };
  }
  notifications.set(id, { request_id: id, message: "New " + service + " request from " + email });
  notificationSendCount += 1;
  state.notified = true;
  return { status: 201, outcome: "accepted", request_id: id };
}

function fixture(request_id) {
  return { request_id, email: "casey@example.invalid", service: "equipment setup" };
}

const scenarios = [
  { name: "New request", payload: fixture("demo-001"), status: 201, outcome: "accepted", rows: 1, alerts: 1 },
  { name: "Replay exact payload", payload: fixture("demo-001"), status: 200, outcome: "duplicate_replay", rows: 1, alerts: 1 },
  { name: "Sheet failure", payload: fixture("demo-002"), failure: "sheet", status: 503, outcome: "sheet_unavailable", rows: 1, alerts: 1 },
  { name: "Retry after sheet recovery", payload: fixture("demo-002"), status: 201, outcome: "accepted", rows: 2, alerts: 2 },
  { name: "Notification failure", payload: fixture("demo-003"), failure: "notification", status: 503, outcome: "notification_unavailable", rows: 3, alerts: 2 },
  { name: "Retry notification only", payload: fixture("demo-003"), status: 201, outcome: "accepted", rows: 3, alerts: 3 },
  { name: "Reject ID reuse with different payload", payload: { ...fixture("demo-001"), service: "other" }, status: 409, outcome: "request_id_conflict", rows: 3, alerts: 3 },
];

return scenarios.map(scenario => {
  const result = processRequest(scenario.payload, scenario.failure);
  const passed = result.status === scenario.status && result.outcome === scenario.outcome
    && sheet.size === scenario.rows && notifications.size === scenario.alerts
    && sheetWriteCount === scenario.rows && notificationSendCount === scenario.alerts;
  if (!passed) throw new Error("Unexpected result for " + scenario.name + ": " + JSON.stringify(result));
  return { json: { simulated: true, scenario: scenario.name, passed, ...result, sheet_rows: sheet.size, notifications: notifications.size, simulated_row_writes: sheetWriteCount, simulated_notification_sends: notificationSendCount } };
});
